"""The website's SEO and integrity: metadata, structured data, and that every file it points
at exists. Search engines and link previews fail silently, so these checks are the only alarm."""

from __future__ import annotations

import json
import re
import struct
import unittest
import xml.etree.ElementTree as ET
from html.parser import HTMLParser
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SITE = ROOT / "site"
URL = "https://radufarcas10.github.io/ghis/"
# Copied in or generated by the Pages workflow, so absent from site/ itself.
BUILT = {"theme.js", "favicon.svg", "demo/", "demo/gitlab/", "demo/codeberg/"}


class Page(HTMLParser):
    def __init__(self, text: str) -> None:
        super().__init__()
        self.meta: dict[str, str] = {}
        self.links: dict[str, str] = {}
        self.refs: list[str] = []
        self.tags: list[str] = []
        self.feed(text)

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        a = {k: v or "" for k, v in attrs}
        self.tags.append(tag)
        if tag == "meta":
            key = a.get("name") or a.get("property")
            if key and key not in self.meta:
                self.meta[key] = a.get("content", "")
        if tag == "link" and a.get("rel"):
            self.links[a["rel"]] = a.get("href", "")
        for attr in ("href", "src"):
            if a.get(attr):
                self.refs.append(a[attr])


class WebsiteTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.html = (SITE / "index.html").read_text()
        cls.page = Page(cls.html)

    def test_title_and_description_fit_search_results(self) -> None:
        title = re.search(r"<title>(.*?)</title>", self.html).group(1)
        self.assertLessEqual(len(title), 60, title)
        description = self.page.meta["description"]
        self.assertTrue(50 <= len(description) <= 160, description)
        self.assertEqual(self.page.tags.count("h1"), 1)
        self.assertIn('lang="en"', self.html)

    def test_canonical_and_previews_use_absolute_urls(self) -> None:
        self.assertEqual(self.page.links["canonical"], URL)
        self.assertEqual(self.page.meta["og:url"], URL)
        for key in ("og:image", "twitter:image"):
            self.assertTrue(self.page.meta[key].startswith(URL), key)
        for key in ("og:title", "og:description", "og:image:alt", "twitter:card", "twitter:title"):
            self.assertTrue(self.page.meta.get(key), f"missing {key}")
        self.assertEqual(self.page.meta["twitter:card"], "summary_large_image")

    def test_preview_image_is_the_size_platforms_expect(self) -> None:
        image = SITE / self.page.meta["og:image"].removeprefix(URL)
        width, height = struct.unpack(">II", image.read_bytes()[16:24])  # PNG IHDR
        self.assertEqual((width, height), (1200, 630))
        self.assertEqual(self.page.meta["og:image:width"], "1200")
        self.assertLess(image.stat().st_size, 1_000_000)  # some platforms drop big previews

    def test_structured_data_matches_the_visible_faq(self) -> None:
        block = re.search(r'<script type="application/ld\+json">(.*?)</script>', self.html, re.S)
        graph = {node["@type"]: node for node in json.loads(block.group(1))["@graph"]}
        self.assertEqual(graph["SoftwareApplication"]["offers"]["price"], "0")
        self.assertEqual(
            graph["SoftwareSourceCode"]["codeRepository"], "https://github.com/radufarcas10/ghis"
        )
        pairs = re.findall(r'<summary>(.*?)</summary><div class="answer"><p>(.*?)</p>', self.html)
        visible = [(q, re.sub(r"<[^>]+>", "", a).replace("&#39;", "'")) for q, a in pairs]
        structured = [
            (q["name"], q["acceptedAnswer"]["text"]) for q in graph["FAQPage"]["mainEntity"]
        ]
        self.assertEqual(structured, visible)  # Google requires the markup to match the page

    def test_every_local_reference_exists(self) -> None:
        for ref in self.page.refs:
            if ref.startswith(("http://", "https://", "#", "mailto:")):
                continue
            path = ref.split("#")[0].split("?")[0]  # ?v=2 versions, it is not part of the file
            if path in BUILT:
                continue
            self.assertTrue((SITE / path).exists(), f"site/index.html points at missing {ref}")

    def test_every_stylesheet_reference_exists(self) -> None:
        # A missing mask image (the footer logo) fails silently: the element just disappears.
        css = (SITE / "site.css").read_text()
        for ref in re.findall(r"url\(([^)]+)\)", css):
            ref = ref.strip("'\"")
            if not ref.startswith(("data:", "http")):
                self.assertTrue((SITE / ref).exists(), f"site.css points at missing {ref}")

    def test_sources_carry_no_hand_written_versions(self) -> None:
        # Fingerprints (?v=) are added on the way out: by write_site, the server and the Pages
        # build. A hand-written one in a source file would silently go stale.
        for page in [
            *SITE.glob("*.html"),
            SITE / "site.webmanifest",
            *(ROOT / "src" / "ghis" / "web").glob("*.html"),
        ]:
            self.assertNotIn("?v=", page.read_text(), page.name)

    def test_sitemap_manifest_and_404(self) -> None:
        ns = {"s": "http://www.sitemaps.org/schemas/sitemap/0.9"}
        urls = ET.parse(SITE / "sitemap.xml").getroot().findall("s:url/s:loc", ns)
        locs = [el.text for el in urls]
        self.assertEqual(locs, [URL])
        manifest = json.loads((SITE / "site.webmanifest").read_text())
        for icon in manifest["icons"]:
            src = icon["src"].split("?")[0]
            if src not in BUILT:
                self.assertTrue((SITE / src).exists(), src)
        self.assertIn('content="noindex"', (SITE / "404.html").read_text())

    def test_inline_icons_are_text_sized_without_css(self) -> None:
        # An SVG without its own size fills its container whenever its CSS is missing or stale
        # (a cached old stylesheet right after a deploy): one huge icon across the page.
        pages = [
            SITE / "index.html",
            SITE / "404.html",
            ROOT / "src" / "ghis" / "web" / "index.html",
            ROOT / "src" / "ghis" / "web" / "connect.html",
            ROOT / "src" / "ghis" / "web" / "connect.js",
        ]
        for page in pages:
            for svg in re.findall(r"<svg\b[^>]*>", page.read_text()):
                self.assertIn("width=", svg, f"{page.name}: {svg[:60]}")

    def test_stories_stay_out_of_search_results(self) -> None:
        story = (ROOT / "src" / "ghis" / "web" / "index.html").read_text()
        self.assertIn('<meta name="robots" content="noindex, nofollow">', story)

    def test_pages_workflow_rewrites_the_address_for_forks(self) -> None:
        workflow = (ROOT / ".github" / "workflows" / "pages.yml").read_text()
        self.assertIn(URL, workflow)  # the sed pattern must track the address used above
        self.assertIn("tools/version_site.py _site", workflow)  # fingerprints, demos included


if __name__ == "__main__":
    unittest.main()
